#[verus::spec]
fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    // Precondition: The input vector must have a non-negative length.
    // Requires: v.len() >= 0
    assert!(v.len() >= 0);
    
    let n = v.len();
    // Invariant: The matrix will have n rows, each of length n.
    let mut matrix = Vec::with_capacity(n);
    
    // Loop invariant: For all i in 0..j, matrix[i] is created correctly.
    for i in 0..n {
        // Ensure: The row created by create_row has the correct diagonal element.
        let row = create_row(&v, i);
        assert!(row.len() == n);
        assert!(row[i] == v[i]);
        matrix.push(row);
    }
    
    // Postcondition: The resulting matrix has n rows and each row has n elements.
    assert!(matrix.len() == n);
    for row in &matrix {
        assert!(row.len() == n);
    }
    
    matrix
}

#[verus::spec]
fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    // Precondition: The index i must be within the bounds of the vector v.
    // Requires: i < v.len()
    assert!(i < v.len());
    
    let n = v.len();
    // Invariant: The row will be filled with 0.0 and have length n.
    let mut row = vec![0.0; n]; // Create a row filled with 0.0
    row[i] = v[i]; // Set the diagonal element
    row
}

